using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor.SceneManagement;
namespace CorseVR.Editor {
public static class FinitionV7Layout {
 const string A="Assets/Prototype_Maquis/Art/FinitionV7";
 static Dictionary<Material,Material> mats=new Dictionary<Material,Material>();
 static void Record(Component c){EditorUtility.SetDirty(c);PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
 static Texture2D Tx(string n){return AssetDatabase.LoadAssetAtPath<Texture2D>(A+"/Textures/"+n+".png");}
 public static void Prepare(){AssetDatabase.Refresh();foreach(var guid in AssetDatabase.FindAssets("t:Model",new[]{A+"/Models"})){var imp=AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid)) as ModelImporter;imp.isReadable=true;imp.importCameras=false;imp.importLights=false;imp.importNormals=ModelImporterNormals.Import;imp.SaveAndReimport();}foreach(var guid in AssetDatabase.FindAssets("t:Texture2D",new[]{A+"/Textures"})){var imp=AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid)) as TextureImporter;imp.alphaIsTransparency=imp.assetPath.Contains("Feuillages");imp.mipmapEnabled=true;imp.maxTextureSize=2048;imp.anisoLevel=4;imp.textureCompression=TextureImporterCompression.CompressedHQ;imp.wrapMode=imp.alphaIsTransparency?TextureWrapMode.Clamp:TextureWrapMode.Repeat;imp.mipMapsPreserveCoverage=imp.alphaIsTransparency;imp.alphaTestReferenceValue=.48f;imp.SaveAndReimport();}}
 static Material MaterialFor(Material original){if(!original||original.shader.name=="CorseVR/Finition V7 Peinte")return original;Material m;if(mats.TryGetValue(original,out m))return m;string path=A+"/Materials/"+original.name+"_V7.mat";m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(original);m.name=original.name+"_V7";AssetDatabase.CreateAsset(m,path);}if(original.shader.name.Contains("Maquis V2")){m.shader=Shader.Find("CorseVR/Finition V7 Peinte");float mode=m.GetFloat("_Mode");m.SetColor("_ShadowTint",new Color(.43f,.63f,.67f));m.SetFloat("_Roughness",mode<.5f?.77f:.90f);if(mode<.5f){m.SetTexture("_FoliageAtlas",Tx("Feuillages_Corses_Peints"));m.SetTexture("_BarkMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Prototype_Maquis/Art/FoliageReference/Textures/Painted_Bark.png"));}else if(mode>1.5f&&mode<2.5f){m.SetTexture("_BaseMap",Tx("Granit_Peint"));m.SetFloat("_TextureScale",.58f);}else if(mode>2.5f&&mode<3.5f)m.SetTexture("_BaseMap",Tx("Terre_Peinte"));}
  else if(original.shader.name.Contains("Maison Refonte")||original.shader.name.Contains("Maison Peinte")){float mode=m.GetFloat("_Mode");if(mode<.5f){m.SetTexture("_BaseMap",Tx("Granit_Peint"));if(m.HasProperty("_TextureScale"))m.SetFloat("_TextureScale",.65f);if(m.HasProperty("_TextureWeight"))m.SetFloat("_TextureWeight",.55f);}if(m.HasProperty("_Smoothness")&&mode<2.5f)m.SetFloat("_Smoothness",mode>.5f?.15f:.10f);if(m.HasProperty("_Relief"))m.SetFloat("_Relief",.0015f);}
  m.enableInstancing=true;EditorUtility.SetDirty(m);mats[original]=m;return m;}
 static Mesh Fitted(Mesh old,string key){string file=A+"/Models/"+key.Replace("_LOD","_Niveau")+".fbx";var asset=AssetDatabase.LoadAssetAtPath<GameObject>(file);if(!asset)return null;var source=asset.GetComponentInChildren<MeshFilter>().sharedMesh;string path=A+"/Meshes/Fit_"+Hash128.Compute(AssetDatabase.GetAssetPath(old)+old.name+key+old.bounds.ToString()).ToString()+".asset";var cached=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(cached)return cached;var mesh=UnityEngine.Object.Instantiate(source);mesh.name="V7_"+old.name;var a=source.bounds;var b=old.bounds;var scale=new Vector3(b.size.x/Mathf.Max(a.size.x,.000001f),b.size.y/Mathf.Max(a.size.y,.000001f),b.size.z/Mathf.Max(a.size.z,.000001f));var vs=mesh.vertices;for(int i=0;i<vs.Length;i++)vs[i]=b.center+Vector3.Scale(vs[i]-a.center,scale);mesh.vertices=vs;var ns=mesh.normals;for(int i=0;i<ns.Length;i++)ns[i]=new Vector3(ns[i].x/scale.x,ns[i].y/scale.y,ns[i].z/scale.z).normalized;mesh.normals=ns;mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static string Species(LODGroup group){string n=group.name;if(n.StartsWith("Genevrier"))return "Genevrier";return n.Split('_')[0];}
 static int Form(string name,int count){string[] forms={"Jeune","Etale","Dense","Incline","Ancien","Bifurque"};for(int i=0;i<forms.Length;i++)if(name.Contains(forms[i]))return i%count;return 0;}
 static bool ReplacePlant(LODGroup group,bool representative){string species=Species(group);int count=species=="CheneVert"||species=="Arbousier"||species=="Lentisque"?3:species=="Oleastre"?1:2;int form=representative?0:Form(group.name,count);string key="V7_"+species+"_"+form;if(!AssetDatabase.LoadAssetAtPath<GameObject>(A+"/Models/"+key+"_Niveau0.fbx"))return false;var lods=group.GetLODs();for(int level=0;level<lods.Length;level++)foreach(var r in lods[level].renderers){if(!r)continue;var f=r.GetComponent<MeshFilter>();if(!f)continue;var replacement=Fitted(f.sharedMesh,key+"_LOD"+Mathf.Min(level,2));if(replacement){f.sharedMesh=replacement;Record(f);}r.sharedMaterials=r.sharedMaterials.Select(MaterialFor).ToArray();r.shadowCastingMode=level<2?ShadowCastingMode.On:ShadowCastingMode.Off;Record(r);}group.RecalculateBounds();Record(group);return true;}
 static void ReplaceRock(LODGroup group){foreach(var f in group.GetComponentsInChildren<MeshFilter>()){var replacement=Fitted(f.sharedMesh,"V7_Granit_0");if(replacement){f.sharedMesh=replacement;Record(f);}var r=f.GetComponent<Renderer>();r.sharedMaterials=r.sharedMaterials.Select(MaterialFor).ToArray();r.shadowCastingMode=ShadowCastingMode.On;Record(r);}}
 public static string Representatives(){if(EditorApplication.isPlaying)throw new Exception("Edit required");Prepare();var main=GameObject.Find("Maquis_35m").transform;var route=main.GetComponent<Maquis35Route>();var centre=route.WorldAt(8);foreach(var sp in new[]{"CheneVert","Lentisque"}){var g=main.GetComponentsInChildren<LODGroup>().Where(x=>x.name.StartsWith(sp)).OrderBy(x=>Vector3.Distance(x.transform.position,centre)).First();ReplacePlant(g,true);}var rock=main.GetComponentsInChildren<LODGroup>().Where(x=>x.name.Contains("Granit")).OrderBy(x=>Vector3.Distance(x.transform.position,centre)).FirstOrDefault();if(rock)ReplaceRock(rock);var ground=main.Find("01_Terrain_Chemin").GetComponentInChildren<Renderer>();ground.sharedMaterial=MaterialFor(ground.sharedMaterial);Record(ground);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());return "Representative tree, shrub, rock and ground updated";}
 static void Lighting(){var sun=GameObject.Find("Directional Light").GetComponent<Light>();sun.color=new Color(1f,.96f,.86f);sun.intensity=1.15f;sun.shadows=LightShadows.Soft;sun.shadowStrength=.86f;sun.shadowBias=.025f;sun.shadowNormalBias=.18f;sun.transform.rotation=Quaternion.Euler(47,138,0);Record(sun);Record(sun.transform);RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.50f,.66f,.74f);RenderSettings.ambientEquatorColor=new Color(.38f,.48f,.40f);RenderSettings.ambientGroundColor=new Color(.24f,.22f,.17f);RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogColor=new Color(.65f,.77f,.77f);RenderSettings.fogDensity=.012f;
  var sky=new Material(RenderSettings.skybox);sky.name="Ciel_Peint_V7";if(sky.HasProperty("_Zenith"))sky.SetColor("_Zenith",new Color(.27f,.53f,.66f));if(sky.HasProperty("_Horizon"))sky.SetColor("_Horizon",new Color(.74f,.84f,.82f));AssetDatabase.CreateAsset(sky,A+"/Materials/Ciel_Peint_V7.mat");RenderSettings.skybox=sky;
  var go=new GameObject("Finition_Couleur_Exposition_V7");var volume=go.AddComponent<Volume>();volume.isGlobal=true;volume.priority=2;var profile=ScriptableObject.CreateInstance<VolumeProfile>();profile.name="Couleur_Naturelle_V7";var tone=profile.Add<Tonemapping>(true);tone.mode.value=TonemappingMode.ACES;var color=profile.Add<ColorAdjustments>(true);color.postExposure.value=.20f;color.contrast.value=6;color.saturation.value=-4;AssetDatabase.CreateAsset(profile,A+"/Materials/Couleur_Naturelle_V7.asset");foreach(var component in profile.components)AssetDatabase.AddObjectToAsset(component,profile);EditorUtility.SetDirty(profile);volume.sharedProfile=profile;var cam=Camera.main.GetComponent<UniversalAdditionalCameraData>();if(!cam)cam=Camera.main.gameObject.AddComponent<UniversalAdditionalCameraData>();cam.renderPostProcessing=true;cam.antialiasing=AntialiasingMode.FastApproximateAntialiasing;Record(cam);
 }
 public static string All(){if(EditorApplication.isPlaying)throw new Exception("Edit required");Prepare();int changed=0;foreach(var g in UnityEngine.Object.FindObjectsByType<LODGroup>()){if(ReplacePlant(g,false))changed++;}foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>()){if(r.sharedMaterials.Any(m=>m&&(m.shader.name.Contains("Maquis V2")||m.shader.name.Contains("Maison Refonte")||m.shader.name.Contains("Maison Peinte")))){r.sharedMaterials=r.sharedMaterials.Select(MaterialFor).ToArray();Record(r);}if(r.name.Contains("Granit")&&!r.name.Contains("Collision")){r.shadowCastingMode=ShadowCastingMode.On;Record(r);}}
  ImproveRocks();Lighting();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());return changed+" plant groups rebuilt, materials and lighting harmonized across accessible zones";}
 static void ImproveRocks(){var main=GameObject.Find("Maquis_35m").transform;var ext=GameObject.Find("Extension_Tour_Littoral").transform;var filters=main.Find("10_Refonte_Botanique_V2/E_Roches").GetComponentsInChildren<MeshFilter>().Concat(ext.Find("04_Rochers_Littoral").GetComponentsInChildren<MeshFilter>());foreach(var f in filters){var source=PrefabUtility.GetOutermostPrefabInstanceRoot(f.gameObject);string name=source?source.name:f.sharedMesh.name;int variant=name.Contains("_2")?2:name.Contains("_3")?3:0;if(name.Contains("_1")||name.Contains("_4")||name.Contains("_5")||name.Contains("_6")||name.Contains("_7"))continue;var mesh=Fitted(f.sharedMesh,"V7_Granit_"+variant);if(mesh){f.sharedMesh=mesh;Record(f);}var r=f.GetComponent<Renderer>();r.sharedMaterial=MaterialFor(r.sharedMaterial);r.shadowCastingMode=ShadowCastingMode.On;Record(r);}}
}
}
